// Input: assumes incoming data has 'textAsHtml' field
const html = items[0].json.textAsHtml || '';

// Basic function to decode HTML entities
function decodeEntities(text) {
  const entities = {
    '&amp;': '&',
    '&lt;': '<',
    '&gt;': '>',
    '&quot;': '"',
    '&#39;': "'",
    '&nbsp;': ' '
  };
  return text.replace(/&[^;]+;/g, match => entities[match] || match);
}

// Strip tags and decode
const plainText = decodeEntities(html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim());

return [{ json: { plainText } }];

// Assume incoming data has 'plainText' field from previous node
const items = $input.all();  // Get all items, but likely just one

return items.map(item => {
  const text = item.json.plainText || '';

  // Extract Name: after "Name: " until before next label or end
  const nameMatch = text.match(/Name:\s*([\s\S]*?)\s*(Phone:|Email:|$)/i);
  const name = nameMatch ? nameMatch[1].trim() : 'Not found';

  // Extract Phone: after "Phone: " until before next label or end
  const phoneMatch = text.match(/Phone:\s*([\s\S]*?)\s*(Email:|Looking forward|$)/i);
  const phone = phoneMatch ? phoneMatch[1].trim() : 'Not found';

  // Extract Model: from "Model X200" capturing X200
  const modelMatch = text.match(/Model\s*([\w\d]+)/i);  // Updated to capture alphanumeric
  const model = modelMatch ? modelMatch[1].trim() : 'Not found';

  return { json: { name, phone, model } };
});

